// Catalog rebuild hook: POST /_hooks/catalog
//
// index.json and osism/images.yml are generated by the oic-website build, which
// otherwise runs on pushes to its main branch and once a day. A release that
// republishes an image moves latest/ and the artifact digests right away, so
// clients that verify signatures against index.json (oic-sync) would refuse the
// image until the next site build. The reusable build workflows call this hook
// at the end of a release; the Worker then dispatches the site deploy with the
// GH_DISPATCH_TOKEN it already holds for the daily scheduler.
//
// Authentication: a GitHub Actions OIDC token (no shared secret). Accepted when
// it is valid, issued for HOOK_AUDIENCE, and comes from a workflow of the
// open-img-cloud organisation running from a main branch.

import { dispatchAll } from "./scheduler.js";

export const HOOK_PATH = "/_hooks/catalog";
export const HOOK_AUDIENCE = "https://images.openimages.cloud/_hooks/catalog";
export const CATALOG_DEPLOY = "oic-website:deploy.yml";

const ISSUER = "https://token.actions.githubusercontent.com";
const JWKS_URL = `${ISSUER}/.well-known/jwks`;
const ORG = "open-img-cloud";
// <org>/<repo>/.github/workflows/<file>.yml@refs/heads/main
const WORKFLOW_REF = /^open-img-cloud\/[A-Za-z0-9._-]+\/\.github\/workflows\/[A-Za-z0-9._-]+\.ya?ml@refs\/heads\/main$/;
const CLOCK_SKEW = 60;

const JSON_HEADERS = { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" };

function b64urlDecode(s) {
  const pad = s.length % 4 === 0 ? "" : "=".repeat(4 - (s.length % 4));
  const bin = atob(s.replace(/-/g, "+").replace(/_/g, "/") + pad);
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

function decodeJson(part) {
  return JSON.parse(new TextDecoder().decode(b64urlDecode(part)));
}

async function fetchJwks(fetchImpl) {
  const res = await fetchImpl(JWKS_URL, { cf: { cacheTtl: 3600, cacheEverything: true } });
  if (!res.ok) throw new Error(`JWKS fetch failed: HTTP ${res.status}`);
  const body = await res.json();
  return Array.isArray(body.keys) ? body.keys : [];
}

/**
 * Verifies a GitHub Actions OIDC token and returns its claims, or throws.
 * `now` is in seconds (injectable for tests).
 */
export async function verifyGithubOidc(token, { fetchImpl = fetch, now = Date.now() / 1000 } = {}) {
  const parts = (token || "").split(".");
  if (parts.length !== 3) throw new Error("malformed token");
  const header = decodeJson(parts[0]);
  const claims = decodeJson(parts[1]);
  if (header.alg !== "RS256") throw new Error(`unsupported alg ${header.alg}`);

  const jwk = (await fetchJwks(fetchImpl)).find((k) => k.kid === header.kid);
  if (!jwk) throw new Error("unknown signing key");
  const key = await crypto.subtle.importKey(
    "jwk",
    { kty: jwk.kty, n: jwk.n, e: jwk.e, alg: "RS256", ext: true },
    { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" },
    false,
    ["verify"],
  );
  const signed = new TextEncoder().encode(`${parts[0]}.${parts[1]}`);
  const valid = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64urlDecode(parts[2]), signed);
  if (!valid) throw new Error("bad signature");

  if (claims.iss !== ISSUER) throw new Error("wrong issuer");
  const aud = Array.isArray(claims.aud) ? claims.aud : [claims.aud];
  if (!aud.includes(HOOK_AUDIENCE)) throw new Error("wrong audience");
  if (typeof claims.exp !== "number" || claims.exp < now - CLOCK_SKEW) throw new Error("expired");
  if (typeof claims.nbf === "number" && claims.nbf > now + CLOCK_SKEW) throw new Error("not yet valid");
  if (claims.repository_owner !== ORG) throw new Error("wrong organisation");
  if (!WORKFLOW_REF.test(claims.job_workflow_ref || "")) throw new Error("workflow not allowed");
  return claims;
}

export async function handleCatalogHook(request, env, ctx, fetchImpl = fetch) {
  if (request.method !== "POST") {
    return new Response(JSON.stringify({ error: "use POST" }), {
      status: 405,
      headers: { ...JSON_HEADERS, allow: "POST" },
    });
  }
  const auth = request.headers.get("authorization") || "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";
  let claims;
  try {
    claims = await verifyGithubOidc(token, { fetchImpl });
  } catch (err) {
    return new Response(JSON.stringify({ error: `unauthorized: ${err.message}` }), {
      status: 401,
      headers: JSON_HEADERS,
    });
  }
  const results = await dispatchAll(env, fetchImpl, CATALOG_DEPLOY);
  const ok = results.length > 0 && results.every((r) => r.ok);
  console.log(`hooks: catalog rebuild requested by ${claims.repository} (${claims.job_workflow_ref}): ${ok}`);
  return new Response(JSON.stringify({ dispatched: ok, repository: claims.repository }), {
    status: ok ? 202 : 502,
    headers: JSON_HEADERS,
  });
}
